with enriched as (select *, avg(amount) over (partition by txn_type order by amount, id rows between 5 preceding and current row) as amount_avg_5, percent_rank() over (partition by account_id order by amount desc nulls last) as amount_percent_rank, row_number() over (partition by txn_type order by txn_time, id) as event_seq, rank() over w_part as amount_rank from transactions window w_part as (partition by txn_type order by amount nulls first)) select id, account_id, txn_type, is_flagged, amount_avg_5, amount_percent_rank, event_seq, amount_rank, case when txn_type rlike '^(REFUND|FEE)$' then 'EXTENDED' else 'PRIORITY' end as txn_type_zone from enriched
